impl IrSummaryCounts {
    fn visit_function(&mut self, function: &FunctionIr) {
        if function.is_nested {
            self.nested_functions += 1;
        }
        if function.is_expression {
            self.function_exprs += 1;
        }
        if function.flavor == FunctionFlavor::Arrow {
            self.arrow_functions += 1;
        }
        if function.is_named_expression {
            self.named_function_exprs += 1;
        }
        if !function.captured_bindings.is_empty() || !function.owned_env_bindings.is_empty() {
            self.closures += 1;
        }
        self.captures += function.captured_bindings.len();
        if function.captures_lexical_this {
            self.lexical_this_captures += 1;
        }
        if function.captures_lexical_arguments {
            self.lexical_arguments_captures += 1;
        }
        for param in &function.params {
            if param.default_init.is_some() {
                self.default_params += 1;
            }
            if param.is_rest {
                self.rest_params += 1;
            }
        }
        if function.class_heritage_kind == ClassHeritageKind::Null && function.uses_super {
            self.null_heritage_super_uses += 1;
        }
        self.visit_block(&function.body);
    }

    fn visit_block(&mut self, block: &BlockIr) {
        for statement in &block.statements {
            self.visit_statement(statement);
        }
    }

    fn visit_statement(&mut self, statement: &StatementIr) {
        self.statements += 1;
        match statement {
            StatementIr::Empty => {}
            StatementIr::Lexical { mode, init, .. } => {
                match mode {
                    BindingMode::Let => self.lets += 1,
                    BindingMode::Const => self.consts += 1,
                    BindingMode::Var => self.vars += 1,
                }
                self.visit_expr(init);
            }
            StatementIr::LexicalBlock(statements) => {
                for statement in statements {
                    self.visit_statement(statement);
                }
            }
            StatementIr::Var(declarators) => {
                self.vars += declarators.len();
                for declarator in declarators {
                    if let Some(init) = &declarator.init {
                        self.visit_expr(init);
                    }
                }
            }
            StatementIr::Expression(expr) => self.visit_expr(expr),
            StatementIr::Block(block) => {
                self.blocks += 1;
                self.visit_block(block);
            }
            StatementIr::If {
                condition,
                then_branch,
                else_branch,
            } => {
                self.ifs += 1;
                self.visit_expr(condition);
                self.visit_statement(then_branch);
                if let Some(else_branch) = else_branch {
                    self.visit_statement(else_branch);
                }
            }
            StatementIr::While { condition, body } => {
                self.whiles += 1;
                self.visit_expr(condition);
                self.visit_statement(body);
            }
            StatementIr::DoWhile { body, condition } => {
                self.do_whiles += 1;
                self.visit_statement(body);
                self.visit_expr(condition);
            }
            StatementIr::For {
                init,
                test,
                update,
                body,
            } => {
                self.fors += 1;
                if let Some(init) = init {
                    self.visit_for_init(init);
                }
                if let Some(test) = test {
                    self.visit_expr(test);
                }
                if let Some(update) = update {
                    self.visit_expr(update);
                }
                self.visit_statement(body);
            }
            StatementIr::ForOfArray { iterable, body, .. }
            | StatementIr::ForInArray {
                target: iterable,
                body,
                ..
            }
            | StatementIr::ForInString {
                target: iterable,
                body,
                ..
            }
            | StatementIr::ForInObject {
                target: iterable,
                body,
                ..
            } => {
                self.fors += 1;
                self.visit_expr(iterable);
                self.visit_statement(body);
            }
            StatementIr::Switch {
                discriminant,
                cases,
            } => {
                self.switches += 1;
                self.visit_expr(discriminant);
                for case in cases {
                    if let Some(condition) = &case.condition {
                        self.visit_expr(condition);
                    }
                    self.visit_block(&case.body);
                }
            }
            StatementIr::Labelled { labels, statement } => {
                self.labels += labels.len();
                self.visit_statement(statement);
            }
            StatementIr::Debugger => self.debuggers += 1,
            StatementIr::Throw(expr) => {
                self.throws += 1;
                self.visit_expr(expr);
            }
            StatementIr::TryCatch {
                try_block,
                catch_block,
                ..
            } => {
                self.try_catches += 1;
                self.visit_block(try_block);
                self.visit_block(catch_block);
            }
            StatementIr::TryFinally {
                try_block,
                finally_block,
            } => {
                self.try_finallys += 1;
                self.visit_block(try_block);
                self.visit_block(finally_block);
            }
            StatementIr::TryCatchFinally {
                try_block,
                catch_block,
                finally_block,
                ..
            } => {
                self.try_finallys += 1;
                self.visit_block(try_block);
                self.visit_block(catch_block);
                self.visit_block(finally_block);
            }
            StatementIr::Return(expr) => {
                self.returns += 1;
                self.visit_expr(expr);
            }
            StatementIr::Break { .. } => self.breaks += 1,
            StatementIr::Continue { .. } => self.continues += 1,
        }
    }

    fn visit_for_init(&mut self, init: &ForInitIr) {
        match init {
            ForInitIr::Lexical { mode, init, .. } => {
                match mode {
                    BindingMode::Let => self.lets += 1,
                    BindingMode::Const => self.consts += 1,
                    BindingMode::Var => self.vars += 1,
                }
                self.visit_expr(init);
            }
            ForInitIr::Var(declarators) => {
                self.vars += declarators.len();
                for declarator in declarators {
                    if let Some(init) = &declarator.init {
                        self.visit_expr(init);
                    }
                }
            }
            ForInitIr::Expression(expr) => self.visit_expr(expr),
        }
    }

    fn visit_expr(&mut self, expr: &TypedExpr) {
        if expr.heap_shape.is_some() {
            self.heap_shapes += 1;
        }
        if !expr.possible_kinds.is_singleton() {
            self.kind_unions += 1;
        }
        if expr.kind == ValueKind::Function {
            self.function_values += 1;
        }
        match &expr.expr {
            ExprIr::AssignIdentifier { value, .. } => {
                self.assignments += 1;
                self.visit_expr(value);
            }
            ExprIr::GlobalPropertyRead { .. } => {
                self.global_property_reads += 1;
            }
            ExprIr::GlobalPropertyWrite {
                value, implicit, ..
            } => {
                self.assignments += 1;
                self.global_property_writes += 1;
                self.implicit_globals += usize::from(*implicit);
                self.visit_expr(value);
            }
            ExprIr::ObjectLiteral(properties) => {
                self.objects += 1;
                for property in properties {
                    match property {
                        ObjectPropertyIr::Data {
                            value,
                            is_shorthand,
                            ..
                        } => {
                            if *is_shorthand {
                                self.object_shorthands += 1;
                            }
                            self.visit_expr(value);
                        }
                        ObjectPropertyIr::ComputedData { key, value } => {
                            self.visit_expr(key);
                            self.visit_expr(value);
                        }
                        ObjectPropertyIr::Method { function, .. } => {
                            self.object_methods += 1;
                            self.visit_expr(function);
                        }
                        ObjectPropertyIr::Getter { function, .. } => {
                            self.object_getters += 1;
                            self.visit_expr(function);
                        }
                        ObjectPropertyIr::Setter { function, .. } => {
                            self.object_setters += 1;
                            self.visit_expr(function);
                        }
                    }
                }
            }
            ExprIr::ArrayLiteral(elements) => {
                self.arrays += 1;
                for element in elements {
                    self.visit_expr(element);
                }
            }
            ExprIr::PropertyRead { target, key } => {
                self.property_reads += 1;
                if matches!(key, PropertyKeyIr::ArrayLength) {
                    self.array_lengths += 1;
                }
                if matches!(key, PropertyKeyIr::StaticString(name) if name == "prototype") {
                    self.prototype_reads += 1;
                }
                self.visit_expr(target);
                self.visit_property_key(key);
            }
            ExprIr::PropertyWrite { target, key, value } => {
                self.property_writes += 1;
                if matches!(key, PropertyKeyIr::StaticString(name) if name == "prototype") {
                    self.prototype_writes += 1;
                }
                self.visit_expr(target);
                self.visit_property_key(key);
                self.visit_expr(value);
            }
            ExprIr::UpdateIdentifier { return_mode, .. } => match return_mode {
                UpdateReturnMode::Prefix => self.prefix_updates += 1,
                UpdateReturnMode::Postfix => self.postfix_updates += 1,
            },
            ExprIr::GlobalPropertyUpdate { return_mode, .. } => {
                self.global_property_writes += 1;
                match return_mode {
                    UpdateReturnMode::Prefix => self.prefix_updates += 1,
                    UpdateReturnMode::Postfix => self.postfix_updates += 1,
                }
            }
            ExprIr::CompoundAssignIdentifier { value, .. } => {
                self.compound_assignments += 1;
                self.visit_expr(value);
            }
            ExprIr::GlobalPropertyCompoundAssign { value, .. } => {
                self.compound_assignments += 1;
                self.global_property_writes += 1;
                self.visit_expr(value);
            }
            ExprIr::UnaryNumber { expr, .. }
            | ExprIr::StringFromCharCode { code: expr }
            | ExprIr::LogicalNot { expr } => {
                self.visit_expr(expr);
            }
            ExprIr::Void { expr } => {
                self.void_uses += 1;
                self.visit_expr(expr);
            }
            ExprIr::DeleteValue { expr } => {
                self.deletes += 1;
                self.visit_expr(expr);
            }
            ExprIr::DeleteIdentifier { kind, .. } => {
                self.deletes += 1;
                self.identifier_deletes += 1;
                if matches!(kind, DeleteIdentifierKindIr::Missing) {
                    self.global_deletes += 1;
                }
            }
            ExprIr::DeleteGlobalProperty { .. } => {
                self.deletes += 1;
                self.global_deletes += 1;
            }
            ExprIr::DeleteProperty { target, key } => {
                self.deletes += 1;
                self.visit_expr(target);
                self.visit_property_key(key);
            }
            ExprIr::TypeOf { expr } => {
                self.typeof_uses += 1;
                self.visit_expr(expr);
            }
            ExprIr::TypeOfUnresolvedIdentifier { .. } => {
                self.typeof_uses += 1;
            }
            ExprIr::BinaryNumber { lhs, rhs, .. }
            | ExprIr::CoerciveAdd { lhs, rhs }
            | ExprIr::CoerciveBinaryNumber { lhs, rhs, .. }
            | ExprIr::BitwiseNumber { lhs, rhs, .. }
            | ExprIr::CompareNumber { lhs, rhs, .. }
            | ExprIr::CompareValue { lhs, rhs, .. }
            | ExprIr::StrictEquality { lhs, rhs, .. }
            | ExprIr::LooseEquality { lhs, rhs, .. }
            | ExprIr::AssertSameValue {
                actual: lhs,
                expected: rhs,
                ..
            }
            | ExprIr::StringConcat { lhs, rhs }
            | ExprIr::LogicalShortCircuit { lhs, rhs, .. }
            | ExprIr::Comma { lhs, rhs } => {
                if matches!(&expr.expr, ExprIr::StringConcat { .. }) {
                    self.string_concats += 1;
                }
                if matches!(&expr.expr, ExprIr::CoerciveAdd { .. }) {
                    self.heap_to_primitives += 1;
                    self.heap_coercions += 1;
                }
                if matches!(&expr.expr, ExprIr::LooseEquality { .. }) {
                    self.loose_equalities += 1;
                    if !lhs.possible_kinds.is_subset_of(KindSet::PRIMITIVE_ONLY)
                        || !rhs.possible_kinds.is_subset_of(KindSet::PRIMITIVE_ONLY)
                    {
                        self.heap_loose_equalities += 1;
                        self.heap_coercions += 1;
                    }
                }
                if matches!(&expr.expr, ExprIr::CoerciveBinaryNumber { .. }) {
                    self.coercive_numeric_ops += 1;
                    if !lhs.possible_kinds.is_subset_of(KindSet::PRIMITIVE_ONLY)
                        || !rhs.possible_kinds.is_subset_of(KindSet::PRIMITIVE_ONLY)
                    {
                        self.heap_to_primitives += 1;
                        self.heap_coercions += 1;
                    }
                }
                if matches!(&expr.expr, ExprIr::CompareValue { .. }) {
                    self.coercive_relational_ops += 1;
                    if !lhs.possible_kinds.is_subset_of(KindSet::PRIMITIVE_ONLY)
                        || !rhs.possible_kinds.is_subset_of(KindSet::PRIMITIVE_ONLY)
                    {
                        self.heap_to_primitives += 1;
                        self.heap_coercions += 1;
                    }
                }
                if matches!(
                    &expr.expr,
                    ExprIr::LogicalShortCircuit {
                        op: LogicalBinaryOp::Coalesce,
                        ..
                    }
                ) {
                    self.nullish_ops += 1;
                }
                if matches!(&expr.expr, ExprIr::Comma { .. }) {
                    self.comma_ops += 1;
                }
                self.visit_expr(lhs);
                self.visit_expr(rhs);
            }
            ExprIr::Conditional {
                condition,
                then_expr,
                else_expr,
            } => {
                self.visit_expr(condition);
                self.visit_expr(then_expr);
                self.visit_expr(else_expr);
            }
            ExprIr::CallNamed { args, .. } => {
                self.calls += 1;
                self.global_default_this_calls += 1;
                for arg in args {
                    self.visit_expr(arg);
                }
            }
            ExprIr::RuntimeThrow { .. } => {}
            ExprIr::Arguments => {
                self.arguments_uses += 1;
            }
            ExprIr::CallIndirect { callee, args, .. } => {
                self.calls += 1;
                self.indirect_calls += 1;
                self.global_default_this_calls += 1;
                self.visit_expr(callee);
                for arg in args {
                    self.visit_expr(arg);
                }
            }
            ExprIr::JsonParseStaticReviver { reviver, .. } => {
                self.calls += 1;
                self.indirect_calls += 1;
                self.visit_expr(reviver);
            }
            ExprIr::Construct { callee, args } => {
                self.calls += 1;
                self.indirect_calls += 1;
                self.constructs += 1;
                self.visit_expr(callee);
                for arg in args {
                    self.visit_expr(arg);
                }
            }
            ExprIr::ClassDefinition(class) => {
                self.constructs += 1;
                self.classes += 1;
                self.class_exprs += 1;
                self.class_extends += usize::from(class.heritage_kind != ClassHeritageKind::None);
                self.null_heritage_classes +=
                    usize::from(class.heritage_kind == ClassHeritageKind::Null);
                self.class_fields += class.fields.len();
                self.private_elements +=
                    class.fields.iter().filter(|field| field.is_private).count();
                self.private_elements += class.private_methods.len();
                self.static_blocks += class.static_blocks.len();
                if let Some(heritage) = &class.heritage {
                    self.visit_expr(heritage);
                }
            }
            ExprIr::CallMethod {
                receiver,
                key,
                args,
            } => {
                self.calls += 1;
                self.indirect_calls += 1;
                self.method_calls += 1;
                self.visit_expr(receiver);
                self.visit_property_key(key);
                for arg in args {
                    self.visit_expr(arg);
                }
            }
            ExprIr::This => {
                self.this_reads += 1;
            }
            ExprIr::NewTarget => {
                self.new_target_uses += 1;
            }
            ExprIr::SuperConstruct { args } => {
                self.super_uses += 1;
                self.calls += 1;
                self.indirect_calls += 1;
                for arg in args {
                    self.visit_expr(arg);
                }
            }
            ExprIr::SuperPropertyRead { key } => {
                self.super_uses += 1;
                self.visit_property_key(key);
            }
            ExprIr::SuperPropertyWrite { key, value } => {
                self.super_uses += 1;
                self.visit_property_key(key);
                self.visit_expr(value);
            }
            ExprIr::PrivateRead {
                target,
                private_name_id: _,
            } => {
                self.private_elements += 1;
                self.visit_expr(target);
            }
            ExprIr::PrivateWrite {
                target,
                private_name_id: _,
                value,
            } => {
                self.private_elements += 1;
                self.visit_expr(target);
                self.visit_expr(value);
            }
            ExprIr::PrivateIn {
                private_name_id: _,
                rhs,
            } => {
                self.private_in_checks += 1;
                self.visit_expr(rhs);
            }
            ExprIr::InstanceOf { lhs, rhs } => {
                self.instanceofs += 1;
                self.visit_expr(lhs);
                self.visit_expr(rhs);
            }
            ExprIr::In { lhs, rhs } => {
                self.in_ops += 1;
                self.visit_expr(lhs);
                self.visit_expr(rhs);
            }
            ExprIr::Undefined
            | ExprIr::ArrayHole
            | ExprIr::Null
            | ExprIr::Boolean(_)
            | ExprIr::Number(_)
            | ExprIr::BigInt(_)
            | ExprIr::String(_)
            | ExprIr::FunctionValue(_)
            | ExprIr::Identifier(_) => {
                if matches!(&expr.expr, ExprIr::Identifier(name) if name == GLOBAL_THIS_NAME) {
                    self.global_this_uses += 1;
                }
            }
        }
    }

    fn visit_property_key(&mut self, key: &PropertyKeyIr) {
        match key {
            PropertyKeyIr::StaticString(_) | PropertyKeyIr::ArrayLength => {}
            PropertyKeyIr::StringExpr(expr) | PropertyKeyIr::ArrayIndex(expr) => {
                self.visit_expr(expr)
            }
        }
    }
}

pub fn lower(source: &SourceUnit) -> ProgramIr {
    let mut program = ProgramIr {
        goal: source.goal,
        stages: vec![LoweringStage::ParsedSource],
        source_len: source.source_text.len(),
        invariants: vec![
            "direct-js-to-wasm-only",
            "no-shipped-interpreter-in-wasm",
            "spec-ir-is-semantic-source-of-truth",
        ],
        diagnostics: Vec::new(),
        script: None,
    };

    let lowered_source;
    let script_source = match source.goal {
        ParseGoal::Script => source,
        ParseGoal::Module => match lower_supported_module_source(source) {
            Ok(source_text) => {
                lowered_source = SourceUnit {
                    goal: ParseGoal::Script,
                    filename: source.filename.clone(),
                    source_text,
                };
                &lowered_source
            }
            Err(message) => {
                program.diagnostics.push(IrDiagnostic {
                    kind: IrDiagnosticKind::Unsupported,
                    message,
                });
                program
                    .stages
                    .push(LoweringStage::UnsupportedFeaturesRecorded);
                return program;
            }
        },
    };

    match reparse_script(script_source) {
        Ok((script, interner)) => {
            program.stages.push(LoweringStage::AstReparsed);
            let analysis = AnalysisBuilder::default().finish(
                &script,
                &interner,
                script_source.source_text.as_str(),
            );
            let lowered = ScriptLowerer::new(
                &interner,
                &analysis,
                script_source.source_text.as_str(),
                SCRIPT_OWNER_ID.to_string(),
            )
            .lower(&script);
            program.script = Some(ScriptIr {
                functions: lowered.functions,
                body: lowered.body,
                owned_env_bindings: lowered.owned_env_bindings,
                global_bindings: lowered.global_bindings,
                host_builtins: lowered.host_builtins,
                builtin_ctor_calls: lowered.builtin_ctor_calls,
                builtin_static_calls: lowered.builtin_static_calls,
                error_builtin_calls: lowered.error_builtin_calls,
                aggregate_errors: lowered.aggregate_errors,
                function_proto_calls: lowered.function_proto_calls,
                function_proto_applies: lowered.function_proto_applies,
                function_proto_binds: lowered.function_proto_binds,
                function_proto_to_strings: lowered.function_proto_to_strings,
                bound_functions: lowered.bound_functions,
                bound_function_constructs: lowered.bound_function_constructs,
                boxed_builtin_calls: lowered.boxed_builtin_calls,
                boxed_builtin_constructs: lowered.boxed_builtin_constructs,
                boxed_receiver_adaptations: lowered.boxed_receiver_adaptations,
                top_level_this_uses: lowered.top_level_this_uses,
                host_builtin_calls: lowered.host_builtin_calls,
                error_proto_to_strings: lowered.error_proto_to_strings,
            });
            program.stages.push(LoweringStage::ScriptIrBuilt);
            if !lowered.diagnostics.is_empty() {
                program
                    .stages
                    .push(LoweringStage::UnsupportedFeaturesRecorded);
            } else {
                program.stages.push(LoweringStage::WasmReady);
            }
            program.diagnostics = lowered.diagnostics;
        }
        Err(message) => {
            let kind = if message.to_ascii_lowercase().contains("unsupported") {
                IrDiagnosticKind::Unsupported
            } else {
                IrDiagnosticKind::Lowering
            };
            program.diagnostics.push(IrDiagnostic { kind, message });
        }
    }

    program
}

fn reparse_script(source: &SourceUnit) -> Result<(Script, Interner), String> {
    let mut interner = Interner::default();
    let scope = Scope::new_global();
    let parser_source = if let Some(filename) = &source.filename {
        Source::from_bytes(source.source_text.as_bytes()).with_path(std::path::Path::new(filename))
    } else {
        Source::from_bytes(source.source_text.as_bytes())
    };
    let script = match panic::catch_unwind(AssertUnwindSafe(|| {
        Parser::new(parser_source).parse_script(&scope, &mut interner)
    })) {
        Ok(Ok(script)) => script,
        Ok(Err(err)) => return Err(format!("lowering reparse failed: {err}")),
        Err(payload) => {
            return Err(format!(
                "unsupported in porffor wasm-aot first slice: frontend parser aborted while reparsing source ({})",
                parser_abort_message(&payload)
            ));
        }
    };
    Ok((script, interner))
}

fn lower_supported_module_source(source: &SourceUnit) -> Result<String, String> {
    let mut interner = Interner::default();
    let scope = Scope::new_global();
    let parser_source = if let Some(filename) = &source.filename {
        Source::from_bytes(source.source_text.as_bytes()).with_path(std::path::Path::new(filename))
    } else {
        Source::from_bytes(source.source_text.as_bytes())
    };
    let module = match panic::catch_unwind(AssertUnwindSafe(|| {
        Parser::new(parser_source).parse_module(&scope, &mut interner)
    })) {
        Ok(Ok(module)) => module,
        Ok(Err(err)) => return Err(format!("lowering module reparse failed: {err}")),
        Err(payload) => {
            return Err(format!(
                "unsupported in porffor wasm-aot first slice: frontend parser aborted while reparsing module source ({})",
                parser_abort_message(&payload)
            ));
        }
    };

    for item in module.items().items() {
        match item {
            ModuleItem::StatementListItem(_) => {}
            ModuleItem::ImportDeclaration(_) => {
                return Err(
                    "unsupported in porffor wasm-aot first slice: module imports".to_string(),
                );
            }
            ModuleItem::ExportDeclaration(export) => match export.as_ref() {
                ExportDeclaration::List(_)
                | ExportDeclaration::VarStatement(_)
                | ExportDeclaration::Declaration(_) => {}
                ExportDeclaration::ReExport { .. } => {
                    return Err(
                        "unsupported in porffor wasm-aot first slice: module re-exports"
                            .to_string(),
                    );
                }
                ExportDeclaration::DefaultFunctionDeclaration(_)
                | ExportDeclaration::DefaultGeneratorDeclaration(_)
                | ExportDeclaration::DefaultAsyncFunctionDeclaration(_)
                | ExportDeclaration::DefaultAsyncGeneratorDeclaration(_)
                | ExportDeclaration::DefaultClassDeclaration(_)
                | ExportDeclaration::DefaultAssignmentExpression(_) => {
                    return Err(
                        "unsupported in porffor wasm-aot first slice: default exports".to_string(),
                    );
                }
            },
        }
    }

    strip_supported_export_syntax(&source.source_text)
}

fn parser_abort_message(payload: &Box<dyn core::any::Any + Send>) -> String {
    if let Some(message) = payload.downcast_ref::<&'static str>() {
        (*message).to_string()
    } else if let Some(message) = payload.downcast_ref::<String>() {
        message.clone()
    } else {
        "non-string abort payload".to_string()
    }
}

fn strip_supported_export_syntax(source: &str) -> Result<String, String> {
    let bytes = source.as_bytes();
    let mut out = String::with_capacity(source.len());
    let mut i = 0;
    while i < bytes.len() {
        if is_keyword_at(source, i, "export") {
            i += "export".len();
            i = copy_ws_and_comments(source, i, &mut out);
            if i < bytes.len() && bytes[i] == b'{' {
                i = skip_balanced_export_list(source, i)?;
                i = skip_ws_and_comments(source, i);
                if i < bytes.len() && bytes[i] == b';' {
                    i += 1;
                }
                out.push('\n');
                continue;
            }
            continue;
        }
        let Some(ch) = source[i..].chars().next() else {
            break;
        };
        out.push(ch);
        i += ch.len_utf8();
    }
    Ok(out)
}

fn is_keyword_at(source: &str, index: usize, keyword: &str) -> bool {
    let end = index + keyword.len();
    if end > source.len() || &source[index..end] != keyword {
        return false;
    }
    let before = index
        .checked_sub(1)
        .and_then(|prev| source[..=prev].chars().last());
    let after = source[end..].chars().next();
    !before.is_some_and(is_identifier_part) && !after.is_some_and(is_identifier_part)
}

fn is_identifier_part(ch: char) -> bool {
    ch == '_' || ch == '$' || ch.is_ascii_alphanumeric()
}

fn is_ecmascript_whitespace(ch: char) -> bool {
    matches!(
        ch,
        '\u{0009}'
            | '\u{000A}'
            | '\u{000B}'
            | '\u{000C}'
            | '\u{000D}'
            | '\u{0020}'
            | '\u{00A0}'
            | '\u{1680}'
            | '\u{2000}'
            ..='\u{200A}'
                | '\u{2028}'
                | '\u{2029}'
                | '\u{202F}'
                | '\u{205F}'
                | '\u{3000}'
                | '\u{FEFF}'
    )
}

fn copy_ws_and_comments(source: &str, mut index: usize, out: &mut String) -> usize {
    let bytes = source.as_bytes();
    loop {
        if index >= bytes.len() {
            return index;
        }
        let Some(ch) = source[index..].chars().next() else {
            return index;
        };
        if ch.is_whitespace() {
            out.push(ch);
            index += ch.len_utf8();
            continue;
        }
        if bytes[index..].starts_with(b"//") {
            let start = index;
            index += 2;
            while index < bytes.len() && bytes[index] != b'\n' {
                index += 1;
            }
            out.push_str(&source[start..index]);
            continue;
        }
        if bytes[index..].starts_with(b"/*") {
            let start = index;
            index += 2;
            while index + 1 < bytes.len() && !bytes[index..].starts_with(b"*/") {
                index += 1;
            }
            index = (index + 2).min(bytes.len());
            out.push_str(&source[start..index]);
            continue;
        }
        return index;
    }
}

fn skip_ws_and_comments(source: &str, mut index: usize) -> usize {
    let mut ignored = String::new();
    index = copy_ws_and_comments(source, index, &mut ignored);
    index
}

fn skip_balanced_export_list(source: &str, mut index: usize) -> Result<usize, String> {
    let bytes = source.as_bytes();
    let mut depth = 0usize;
    while index < bytes.len() {
        match bytes[index] {
            b'{' => depth += 1,
            b'}' => {
                depth = depth.saturating_sub(1);
                index += 1;
                if depth == 0 {
                    return Ok(index);
                }
                continue;
            }
            b'\'' | b'"' => {
                let quote = bytes[index];
                index += 1;
                while index < bytes.len() {
                    if bytes[index] == b'\\' {
                        index = (index + 2).min(bytes.len());
                    } else if bytes[index] == quote {
                        index += 1;
                        break;
                    } else {
                        index += 1;
                    }
                }
                continue;
            }
            _ => {}
        }
        index += 1;
    }
    Err("unsupported in porffor wasm-aot first slice: malformed export list".to_string())
}

